async function viewActe(e){const[t,a,n,d]=await Promise.all([api("/documents"),api("/family/members"),api("/vehicles"),api("/properties")]),s=today(),i=[["",tr("Family (general)")],...a.map(e=>["user:"+e.id,tr("Person")+": "+e.name]),...n.map(e=>["vehicle:"+e.id,tr("Vehicle")+": "+e.name]),...d.map(e=>["property:"+e.id,tr("Property")+": "+e.name])],r=t.filter(e=>e.expiry_date).map(e=>({d:e,days:Math.ceil((new Date(e.expiry_date)-new Date(s))/864e5)})).filter(e=>e.days<=60).sort((e,t)=>e.days-t.days);e.innerHTML=`<div class="pagehead"><div><h1>Acte</h1><p>ID cards, passports, certificates, talon auto, contracts — linked to a person, vehicle or property, with expiry reminders and scans.</p></div></div>\n    ${r.length?`<div class="card" style="margin-bottom:16px"><h3 style="margin-top:0">${tr("Expiring soon")}</h3>\n      <div class="dchips">${r.map(({d:e,days:t})=>`<span class="dchip ${daysClass(t)}">${esc(e.name)} <b>${daysLabel(t)}</b> <span class="dchip-d">${fdate(e.expiry_date)}</span></span>`).join("")}</div></div>`:""}\n    ${canWrite()?addBox("Add document",`<form id="docform" class="formgrid">\n      <div><label>Name</label><input name="name" placeholder="Carte de identitate, Pasaport…" required></div>\n      <div><label>Series / number</label><input name="number" placeholder="optional"></div>\n      <div><label>Belongs to</label><select name="link">${i.map(([e,t])=>`<option value="${e}">${esc(t)}</option>`).join("")}</select></div>\n      <div><label>Expiry date</label><input name="expiry_date" type="date"></div>\n      <div><label>Notes</label><input name="notes" placeholder="optional"></div>\n      <div><label>Scan (PDF or photo)</label><input name="file" type="file" accept=".pdf,image/*"></div>\n      <button class="btn">Add document</button></form>`):""}\n    <div class="card" style="margin-top:16px">\n      ${t.length?`<table><thead><tr><th>Document</th><th>Belongs to</th><th>Expires</th><th>Scan</th><th></th></tr></thead><tbody>\n        ${t.map(e=>{let t='<span class="muted">—</span>';if(e.expiry_date){const a=Math.ceil((new Date(e.expiry_date)-new Date(s))/864e5);t=`<span class="${a<0?"badge late":a<=14?"badge unpaid":""}">${fdate(e.expiry_date)} · ${daysLabel(a)}</span>`}return`<tr>\n            <td><b>${esc(e.name)}</b>${e.number?` <span class="muted">${esc(e.number)}</span>`:""}${e.notes?`<br><span class="muted">${esc(e.notes)}</span>`:""}</td>\n            <td>${(e=>e.person_name?`${tr("Person")}: ${esc(e.person_name)}`:e.vehicle_name?`${tr("Vehicle")}: ${esc(e.vehicle_name)}`:e.property_name?`${tr("Property")}: ${esc(e.property_name)}`:tr("Family"))(e)}</td>\n            <td>${t}</td>\n            <td>${e.attachment?`<a href="/api/documents/${e.id}/attachment" target="_blank">view</a>`:canWrite()?`<label class="btn ghost small" style="display:inline-block">attach<input type="file" data-attach="${e.id}" accept=".pdf,image/*" hidden></label>`:"—"}</td>\n            <td class="right">${canWrite()?`<button class="btn danger small" data-del="${e.id}">Delete</button>`:""}</td>\n          </tr>`}).join("")}</tbody></table>`:'<div class="empty"><b>No acte yet</b>Add ID cards, passports and other documents — the ones with an expiry date show up in reminders and alerts.</div>'}\n    </div>`,$("#docform")?.addEventListener("submit",async t=>{t.preventDefault();const a=t.target,n=Object.fromEntries(new FormData(a)),d={name:n.name,number:n.number,expiry_date:n.expiry_date,notes:n.notes};if(n.link){const[e,t]=n.link.split(":");d[e+"_id"]=Number(t)}const s=a.querySelector('input[name="file"]'),i=s?.files?.[0];try{const t=await api("/documents",{method:"POST",body:d});if(i){const a=new FormData;a.append("file",i);try{await api(`/documents/${t.id}/attachment`,{method:"POST",body:a})}catch(t){return toast(tr("Document saved, but the scan failed:")+" "+t.message),void viewActe(e)}}toast("Document added"),viewActe(e)}catch(e){toast(e.message)}}),e.querySelectorAll("[data-del]").forEach(t=>t.onclick=async()=>{await askDelete({en:"document",ro:"documentul",name:rowName(t),detailEn:"Its scan is deleted too.",detailRo:"Se șterge și scanarea."})&&(await api("/documents/"+t.dataset.del,{method:"DELETE"}),viewActe(e))}),e.querySelectorAll("[data-attach]").forEach(t=>t.onchange=async()=>{const a=new FormData;a.append("file",t.files[0]);try{await api(`/documents/${t.dataset.attach}/attachment`,{method:"POST",body:a}),toast("Scan attached"),viewActe(e)}catch(e){toast(e.message)}})}